CREATE TABLE provider_connections (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL CHECK(btrim(name) <> ''), provider TEXT NOT NULL CHECK(provider IN ('git_https','git_ssh','github_app')), secret_ciphertext TEXT, github_app_installation_id BIGINT, github_app_write_enabled BOOLEAN NOT NULL DEFAULT false, revision BIGINT NOT NULL DEFAULT 1, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK((provider = 'github_app' AND github_app_installation_id > 0 AND secret_ciphertext IS NULL) OR (provider IN ('git_https','git_ssh') AND secret_ciphertext IS NOT NULL AND github_app_installation_id IS NULL)), UNIQUE(owner_user_id, name));
ALTER TABLE git_work_surface_details ADD COLUMN connection_id UUID REFERENCES provider_connections(id) ON DELETE RESTRICT;
CREATE INDEX git_work_surface_connection ON git_work_surface_details(connection_id);
